"""Build a self-contained metadata review page using local original images."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
labels=json.loads((ROOT/'results/labels.json').read_text())
gt=json.loads((ROOT.parent/'labels.json').read_text())
issues={}
for source in ROOT.glob('gt_review_issues_batch_*.json'):
    for issue in json.loads(source.read_text()).get('issues',[]):
        for key in issue.get('annotation_ids',[issue.get('annotation_id')]):
            if key is not None:issues.setdefault(str(key),[]).append(issue['reason'])
page='''<!doctype html><html lang="es"><meta charset="utf-8"><title>Revisión de oclusión</title>
<style>*{box-sizing:border-box}body{font:16px system-ui;margin:20px;background:#f4f6fa;color:#142334}button,select,input{font:inherit;padding:7px;margin:4px}main{display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:20px}canvas{width:100%;background:#ddd}#detail{max-height:55vh;object-fit:contain;background:#15202e}summary{padding:12px;cursor:pointer}aside{min-width:0;overflow-wrap:anywhere;background:white;padding:18px;align-self:start;position:sticky;top:10px}.note{font-size:14px}textarea{width:95%;height:80px}#list{max-height:220px;overflow:auto}.item{display:block;width:95%;text-align:left}h1{font-size:25px}</style>
<h1>Revisión del autor de etiquetas de oclusión</h1><p>Etiquetas iniciales asistidas por IA. No son una revisión humana independiente. Revise el contexto completo y el objeto marcado en amarillo. Las otras cajas se muestran en azul.</p>
<p class="note">none: sin obstrucción externa; partial: parte oculta por otro objeto; heavy: mayoría de rasgos oculta con evidencia clara; uncertain: no se puede decidir. El corte por borde se registra aparte. No marque oclusión sólo por tamaño, distancia, perspectiva o ropa de cama normal.</p>
<select id="filter"><option value="all">Todas las instancias</option><option value="flags">Inciertas, confianza media/baja, heavy o borde</option><option value="uncertain">Sólo oclusión incierta</option><option value="gtissues">Posibles problemas GT</option><option value="pending">Sin revisión del autor</option></select><button id="prev">Anterior</button><button id="next">Siguiente</button><input id="jumpid" type="number" placeholder="ID anotación" style="width:130px"><button id="jump">Ir a ID</button><button id="export">Descargar etiquetas revisadas</button><label>Restaurar JSON <input type="file" id="restore" accept=".json"></label><p id="status"></p>
<main><div><p>Detalle del objeto y su contexto inmediato</p><canvas id="detail"></canvas><details open><summary>Fotografía completa para comprobar el contexto</summary><canvas id="canvas"></canvas></details></div><aside><h2 id="title"></h2><p id="meta"></p><p id="gtissue" style="color:#8a2c12;font-weight:600"></p><label>Oclusión <select id="occlusion"><option>none</option><option>partial</option><option>heavy</option><option>uncertain</option></select></label><br><label><input type="checkbox" id="truncation">Cortado por borde</label><br><label>Confianza <select id="confidence"><option>high</option><option>medium</option><option>low</option></select></label><p>Motivo / observación</p><textarea id="reason"></textarea><p id="initial" class="note"></p><p id="reviewbadge" style="font-weight:700"></p><button id="save">Guardar y marcar revisión del autor</button><button id="saveNext">Guardar y siguiente</button><p id="feedback" role="status" aria-live="polite" style="color:#176d32;font-weight:700"></p><p class="note">Los cambios quedan en memoria del navegador. Descargue el JSON antes de cerrar; el archivo original no se modifica.</p><h3>Objetos de esta foto</h3><div id="list"></div></aside></main>
<script>
const data=__LABELS__,gt=__GT__,issues=__ISSUES__;
let records=data.annotations, index=0, ids=[];
const byId=Object.fromEntries(gt.annotations.map(a=>[a.id,a])), images=Object.fromEntries(gt.images.map(a=>[a.id,a])),cats=Object.fromEntries(gt.categories.map(a=>[a.id,a.name]));
const original=Object.fromEntries(records.map(a=>[a.annotation_id,JSON.parse(JSON.stringify(a.initial_ai_label||a))]));
const $=id=>document.getElementById(id),cv=$('canvas'),ctx=cv.getContext('2d');let token=0;
function refresh(){const f=$('filter').value;ids=records.map((r,i)=>i).filter(i=>f==='all'||f==='flags'&&(records[i].occlusion==='uncertain'||records[i].confidence!=='high'||records[i].occlusion==='heavy'||records[i].truncation)||f==='uncertain'&&records[i].occlusion==='uncertain'||f==='gtissues'&&issues[records[i].annotation_id]||f==='pending'&&!records[i].human_reviewed);index=Math.max(0,Math.min(index,ids.length-1));show()}
function show(){if(!ids.length){$('status').textContent='No hay instancias para este filtro.';return}const r=records[ids[index]],a=byId[r.annotation_id],im=images[a.image_id];$('gtissue').textContent=(issues[a.id]||[]).join(' ');$('title').textContent=cats[a.category_id]+' · anotación '+a.id;$('meta').textContent=im.file_name+' · grupo '+im.capture_group+' · '+im.mount+' '+im.lens;$('status').textContent=(index+1)+' / '+ids.length+' · revisadas '+records.filter(r=>r.human_reviewed).length+' / '+records.length;$('occlusion').value=r.occlusion;$('truncation').checked=r.truncation;$('confidence').value=r.confidence;$('reason').value=r.reason||'';$('reviewbadge').textContent=r.human_reviewed?'✓ Esta anotación ya está revisada':'Esta anotación aún no está revisada';$('initial').textContent='Inicial IA: '+original[a.id].occlusion+', truncamiento '+original[a.id].truncation+', confianza '+original[a.id].confidence;
const list=$('list');list.replaceChildren();for(const other of gt.annotations.filter(x=>x.image_id===a.image_id)){const b=document.createElement('button');b.className='item';b.textContent=other.id+' '+cats[other.category_id];b.onclick=()=>{const p=ids.findIndex(i=>records[i].annotation_id===other.id);if(p>=0){index=p;show()}else{alert('Ese objeto está fuera del filtro actual. Seleccione Todas las instancias.')}};list.appendChild(b)}
const img=new Image(),t=++token;img.onload=()=>{if(t!==token)return;const dc=$('detail'),dx=dc.getContext('2d'),[bx,by,bw,bh]=a.bbox,pad=Math.max(bw,bh)*.3,cx=Math.max(0,bx-pad),cy=Math.max(0,by-pad),cw=Math.min(img.naturalWidth-cx,bw+2*pad),ch=Math.min(img.naturalHeight-cy,bh+2*pad);dc.width=cw;dc.height=ch;dx.drawImage(img,cx,cy,cw,ch,0,0,cw,ch);dx.strokeStyle='#ffff00';dx.lineWidth=Math.max(2,cw/200);dx.strokeRect(bx-cx,by-cy,bw,bh);cv.width=img.naturalWidth;cv.height=img.naturalHeight;ctx.drawImage(img,0,0);for(const b of gt.annotations.filter(x=>x.image_id===a.image_id)){const[x,y,w,h]=b.bbox;ctx.strokeStyle=b.id===a.id?'#ffff00':'#1bc9ff';ctx.lineWidth=b.id===a.id?8:3;ctx.strokeRect(x,y,w,h);ctx.font='bold 30px sans-serif';ctx.fillStyle='#111';ctx.fillRect(x,y,90,38);ctx.fillStyle=ctx.strokeStyle;ctx.fillText(b.id,x+3,y+30)}};img.src='../data/'+encodeURIComponent(im.file_name)}
$('jump').onclick=()=>{const id=Number($('jumpid').value);const p=records.findIndex(r=>r.annotation_id===id);if(p<0){alert('ID no encontrado');return}$('filter').value='all';refresh();index=ids.indexOf(p);show()};$('filter').onchange=()=>{index=0;refresh()};$('prev').onclick=()=>{index=Math.max(0,index-1);show()};$('next').onclick=()=>{index=Math.min(ids.length-1,index+1);show()};function saveReview(advance){if(!ids.length)return false;if(!$('reason').value.trim()){$('feedback').textContent='Falta el motivo: escriba una observación antes de guardar.';return false}const r=records[ids[index]],savedId=r.annotation_id;r.occlusion=$('occlusion').value;r.truncation=$('truncation').checked;r.confidence=$('confidence').value;r.reason=$('reason').value;r.human_reviewed=true;r.human_reviewed_at=new Date().toISOString();r.initial_ai_label=original[r.annotation_id];refresh();if(advance&&ids.length&&records[ids[index]].annotation_id===savedId){index=Math.min(ids.length-1,index+1);show()}$('feedback').textContent='✓ Anotación '+savedId+' guardada en esta sesión. Revisadas: '+records.filter(r=>r.human_reviewed).length+' / '+records.length+'. Descargue el JSON para conservarlas.';return true} $('save').onclick=()=>saveReview(false);$('saveNext').onclick=()=>saveReview(true);
$('export').onclick=()=>{const out={...data,annotations:records,status:'ai_labels_with_author_review',author_review_count:records.filter(r=>r.human_reviewed).length};const u=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='occlusion_author_review.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('restore').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.annotations)||d.annotations.length!==records.length||new Set(d.annotations.map(r=>r.annotation_id)).size!==records.length||d.annotations.some(r=>!byId[r.annotation_id]||!['none','partial','heavy','uncertain'].includes(r.occlusion)||r.image_id!==byId[r.annotation_id].image_id||typeof r.truncation!=='boolean'||!['high','medium','low'].includes(r.confidence)||typeof r.reason!=='string'||!r.reason.trim()))throw Error('IDs o etiquetas no válidos');records=d.annotations;refresh()}catch(e){alert(e.message)}};refresh();
</script></html>'''
page=page.replace('__ISSUES__',json.dumps(issues,ensure_ascii=False).replace('<','\\u003c')).replace('__LABELS__',json.dumps(labels,ensure_ascii=False).replace('<','\\u003c')).replace('__GT__',json.dumps(gt,ensure_ascii=False).replace('<','\\u003c'))
(ROOT/'review.html').write_text(page)
print(ROOT/'review.html')
